  let stack=$state<Snapshot[]>([]),instance=0,restored=$state(''),notice=$state('');
  let chosenActions=$state(['theme','fullscreen','xlsx','pdf']),actionOutcome=$state('success'),actionState=$state(''),actionError=$state('');
  let actionToken=0,lastAction='',lastExport=$state<unknown>(null);
