  const flags=[['F01','仅看 Top100'],['F02','仅看重点国代'],['F03','含 YW 客户'],['F04','仅看中资出海']];
  function monthEnd(month:string){return month+'-'+new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate();}
  function log(text:string){events=[text,...events].slice(0,40);}
  function query(reason:string){if(paused){queryPending=true;log(reason+'；依赖候选/可信上下文未就绪，查询暂停');return;}queryPending=false;queries++;log(`#${queries} ${reason}`);}
  function commit(patch:Partial<Applied>,reason:string,run=true){if(pageReadOnly){notice='本页只读：来自上级已锁定的业务视图';return;}if(deferredApply){pendingPatch={...pendingPatch,...patch};log(reason+' · 保留草稿，尚未应用');return;}applied={...applied,...patch};page=1;if(run)query(reason+' · 一次提交');else log(reason+' · 等待候选');}
  function applyDraft(){if(!Object.keys(pendingPatch).length||pageReadOnly)return;const needsModels=('from' in pendingPatch||'mode' in pendingPatch)&&(scene==='time'||scene==='edge');applied={...applied,...pendingPatch};pendingPatch={};page=1;if(needsModels)models();else query('应用全部筛选草稿 · 一次提交');}
  function applyPeriod(next:PeriodRange,anchor:string){if(next.selection.mode==='month'&&next.selection.value>latest&&latestPolicy!=='allow'){notice='所选月超过数据域最新期 '+latest+'，已应用期间保持';return;}commit({period:next,periodAnchor:anchor,month:next.to.slice(0,7)},'统计期间 '+next.selection.mode);}
  function changeRegion(values:string[]){let next={...shown.dims};const valid=groups(values,next['业务类型']??[]);next['协同小组']=(next['协同小组']??[]).filter(v=>valid.includes(v));commit({region:values,dims:next},'区域更新；只校验依赖的协同小组，保留产业/行业等无关条件');}
  function displayDimension(label:string,values:string[]){if(label==='行业')return values.map(id=>industryNodes.flatMap(n=>[n,...n.children]).find(n=>n.id===id)?.label??id).join('、');if(['是否突破','是否上量'].includes(label))return values.map(v=>v==='0'?'否（0）':'是（1）').join('、');return values.join('、');}
  function dimension(label:string,value:string[]){let next={...shown.dims,[label]:value};if(label==='产业'){const valid=value.flatMap(x=>x==='计算'?['基础设施 / 服务器','基础设施 / 网络']:x==='云'?['云服务 / 运维']:x==='存储'?['基础设施 / 存储']:['网络 / 交换机']);const old=next['业务类型']??[];next['业务类型']=old.filter(v=>valid.includes(v));if(next['业务类型'].length!==old.length||!value.length)next['协同小组']=[];}if(label==='业务类型'){const valid=groups(shown.region,value);next['协同小组']=(next['协同小组']??[]).filter(v=>valid.includes(v));}commit({dims:next},label+'更新；只清理失效后代');}
