  function chooseScene(v:string){invalidateTasks();notice='';settingsOpen=['edge','time'].includes(v);scene=v;flowPage='overview';applied=defaults();pendingPatch={};page=1;tab=v==='detail'?'项目概况':'机会点';sort='金额降序';search='';columnStage='';expanded=false;queries=0;stack=[];restored='';candidate=modelState=collabState='ready';pageReadOnly=false;contextReady=true;queryPending=false;identityState='normal';entity=entityAt(0);longTitle=v==='edge';syncUrl();log('切换场景：'+scenes.find(x=>x[0]===v)?.[1]);}
  function cycle(delta:number){variant=layouts[(layouts.findIndex(x=>x[0]===variant)+delta+3)%3][0];syncUrl();log('布局切换 '+variant+'；已应用值不变');}
  function measure(){if(!filterRow)return;const children=Array.from(filterRow.children) as HTMLElement[];if(!children.length)return;const top=children[0].offsetTop;firstCount=children.filter(c=>c.offsetTop===top).length;overflow=firstCount<children.length;firstRowHeight=Math.max(...children.filter(c=>c.offsetTop===top).map(c=>c.offsetHeight));children.forEach(c=>c.inert=dense&&!expanded&&c.offsetTop!==top);}
  onMount(()=>{const ro=new ResizeObserver(measure);ro.observe(filterRow);return()=>ro.disconnect();});
  $effect(()=>{scene;variant;dense;detail;width;expanded;identityState;applied;pendingPatch;pageReadOnly;modelState;tick().then(measure);});
  function money(){minDraft=shown.amount?.min?.toString()??'';maxDraft=shown.amount?.max?.toString()??'';amountError='';moneyPanel.showModal();amountOpen=true;}
  function closeMoney(){moneyPanel.close();amountOpen=false;amountError='';}
  function applyMoney(){const min=minDraft.trim()===''?null:Number(minDraft),max=maxDraft.trim()===''?null:Number(maxDraft);if((min!==null&&(!Number.isFinite(min)||min<0))||(max!==null&&(!Number.isFinite(max)||max<0))||(min!==null&&max!==null&&min>=max)){amountError='请输入有限非负数；双边区间的下限须小于上限。';return;}commit({amount:min===null&&max===null?null:{min,max}},'应用金额范围');closeMoney();}
  function currency(v:string){if(v!==shown.currency)commit({currency:v,amount:null},'切换币种并清空金额');}
  async function models(response=modelResponse,delay=700){const id=++generation;modelLoading=true;modelState='loading';log('模型候选请求代次 '+id+'，范围 '+applied.from+'～'+applied.to);await new Promise(r=>setTimeout(r,delay));if(id!==generation){log('拒绝迟到'+(response==='failed'?'失败':'成功')+'：代次 '+id);return;}modelLoading=false;modelState=response;if(response==='ready'){applied={...applied,dims:{...applied.dims,'模型':(applied.dims['模型']??[]).filter(x=>modelOptions.includes(x))}};query('模型候选就绪，保留合法交集');}else{queryPending=true;log('模型候选 '+stateText[response]+'；保留原合法选值，查询暂停');}}
  function dates(from:string,to:string,nextMode=applied.mode){notice='';const latestValue=['month','singleMonth'].includes(nextMode)?monthEnd(latest):anchor;if(latestPolicy==='latest'&&to>latestValue){notice='超出该数据域最新期 '+latestValue+'；保留上次已应用期间';log('拒绝超出最新期');return;}if(latestPolicy==='complete'&&to>(['month','singleMonth'].includes(nextMode)?monthEnd(latest):'2026-10-18')){notice='所选期间尚未完成；当前仅允许完整期';return;}timeMemory={...timeMemory,[applied.mode]:{from:applied.from,to:applied.to},[nextMode]:{from,to}};const patch:Partial<Applied>={from,to,mode:nextMode};if(nextMode==='singleMonth'){patch.month=from.slice(0,7);patch.periodAnchor=patch.month;patch.period=resolvePeriodSelection({mode:'month',value:patch.month},new Date());}commit(patch,'时间模式/区间更新',false);if(!deferredApply){if(scene==='time'||scene==='edge')models();else query('时间范围应用');}}
  function mode(v:string){if(v==='legacy'){notice='旧系统周编号未知；保留上次合法时间，不发查询。';log('拒绝未知周编码');return;}if(v==='rolling'){dates('2025-10-01','2026-09-30',v);return;}const remembered=timeMemory[v];if(remembered)dates(remembered.from,remembered.to,v);}
  function recentMonths(n:number){const d=new Date(2026,9-n,1);dates(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`,monthEnd(latest),'month');}
  function recent(n:number){const d=new Date(anchor+'T12:00:00');d.setDate(d.getDate()-n+1);dates(d.toISOString().slice(0,10),anchor,'day');}
  function singleMonth(value:string){if(value>latest&&latestPolicy!=='allow'){notice='单月上限为最新期 '+latest+'；未应用超限选择';return;}commit({month:value,periodAnchor:value,period:resolvePeriodSelection({mode:'month',value},new Date())},'详情单月更新');}
  function go(target:string,row?:number,missing=false){if(target==='detail'&&missing){notice='缺少必需项目键，已阻止导航';log('导航输入校验失败：projectId 缺失');return;}if(target==='detail'&&(periodKind==='period'?applied.period.selection.mode!=='month':periodKind!=='singleMonth')){notice='目标详情只接受单月；来源为 '+applied.period.selection.mode+'，请切回月后进入。未强转期间。';log('拒绝不兼容时间粒度');return;}if(target==='detail'&&applied.month>latest){notice='目标详情的最新月为 '+latest+'，来源月份超限；未导航';return;}notice='';const source:Snapshot={applied:clone(applied),page,tab,sort,search,columnStage,scroll:window.scrollY,flowPage,revision,expanded,entity:clone(entity),instance:++instance,settings:{periodKind,latestPolicy,windowMode}};stack=[...stack,source];invalidateTasks();applied={...defaults(),region:[...applied.region],month:applied.month,periodAnchor:applied.periodAnchor,period:clone(applied.period),currency:applied.currency};flowPage=target;windowMode='current';entity=entityAt(row??0);page=1;tab=target==='detail'?'项目概况':'机会点';sort='金额降序';search='';columnStage='';expanded=false;restored='';pendingPatch={};query('显式继承区域/期间/币种'+(target==='detail'?'及实体 '+entity.id:''));window.scrollTo(0,0);}
  async function back(){const s=stack.at(-1);if(!s)return;notice='';invalidateTasks();stack=stack.slice(0,-1);flowPage=s.flowPage;entity=clone(s.entity);periodKind=s.settings.periodKind;latestPolicy=s.settings.latestPolicy;windowMode=s.settings.windowMode;pendingPatch={};if(s.revision!==revision){applied=defaults();page=1;tab='机会点';sort='金额降序';search='';columnStage='';expanded=false;restored='修订变化：不兼容快照已丢弃，恢复合法默认视图';}else{applied=clone(s.applied);page=s.page;tab=s.tab;sort=s.sort;search=s.search;columnStage=s.columnStage;expanded=s.expanded;restored=`已恢复来源 #${s.instance}：筛选、分页（${page}）、排序（${sort}）、Tab（${tab}）、表内搜索、表头条件（${columnStage||'不限'}）、展开、滚动（${s.scroll}px）`;}query('返回来源重新模拟查询');await tick();window.scrollTo(0,s.revision===revision?s.scroll:0);}
  function candidateState(v:string){if(candidateTarget==='region')candidate=v;else if(candidateTarget==='model'){generation++;modelLoading=false;modelState=v;}else collabState=v;log(candidateTarget+'候选状态：'+stateText[v]+'；合法选值保持');if(!paused&&queryPending)query('候选恢复就绪，执行待处理查询');}
  function invalidateContext(){invalidateTasks();contextReady=false;candidate='loading';stack=[];pendingPatch={};applied=defaults();lastExport=null;log('身份修订：旧筛选/返回/导出/异步任务失效');notice='可信上下文变化，正文暂停；重新初始化前不展示旧业务数据';}
  async function initialize(){invalidateTasks();const id=generation;contextReady=false;candidate='loading';log('初始化：默认 → 参数(2026-08) → 导航覆盖(2026-09) → 校验 → 等候授权候选');await new Promise(r=>setTimeout(r,600));if(id!==generation)return;applied=defaults();entity=entityAt(0);contextReady=true;candidate=modelState=collabState='ready';notice='已使用新可信上下文初始化；导航输入覆盖参数，仅模拟一次查询';query('初始化候选就绪');}
  async function full(){if(actionOutcome==='unavailable'){notice='全屏能力不可用，界面保留';return;}try{if(actionOutcome==='failed')throw new Error('演示拒绝');if(document.fullscreenElement)await document.exitFullscreen();else await canvas.requestFullscreen();log('全屏状态切换，可按 Esc 退出');}catch{lastAction='全屏';actionError='全屏请求被拒绝，可以重试';}}
  function action(name:string){if(actionState)return;lastAction=name;if(actionOutcome==='unavailable'){actionError=name+'：能力不可用';return;}const token=++actionToken,outcome=actionOutcome;actionError='';actionState=name;lastExport={target:name.startsWith('XLSX')?'opportunity-table':'整页',applied:clone(applied),request:clone(effectiveRequest),dimensions:clone(effectiveDimensions)};log(name+'：捕获已应用快照并开始模拟任务');setTimeout(()=>{if(token!==actionToken){log(name+'：拒绝旧页面迟到回执');return;}actionState='';if(outcome==='failed'){actionError=name+'：演示失败，可重试';log(actionError);}else{notice=name+'演示完成（未生成文件）';log(name+'：完成');}},900);}
  function retryAction(){if(lastAction==='全屏')full();else action(lastAction);}
  function keyboard(e:KeyboardEvent){if((e.target as HTMLElement).closest('input,textarea,select,button,[contenteditable],dialog,[popover]'))return;if(e.key==='ArrowLeft')cycle(-1);if(e.key==='ArrowRight')cycle(1);}
</script>


<svelte:window onkeydown={keyboard} onscroll={()=>scrollNote=window.scrollY+'px'}/>
<div class="lab">
  <div class="labtop"><div><b>IOC 公共页头</b><span class="prototype">交互原型 · 第一阶段</span></div><button onclick={()=>inspect=!inspect}>{inspect?'收起':'观察'}状态</button><button onclick={()=>coverage=!coverage}>88 项规划</button></div>
  <div class="labtools"><div class="scenes">{#each scenes as s}<button class:active={scene===s[0]} onclick={()=>chooseScene(s[0])}>{s[1]}</button>{/each}</div><div class="widths"><span>容器</span>{#each ['auto','1024','390'] as w}<button class:active={width===w} onclick={()=>width=w}>{w==='auto'?'自适应':w}</button>{/each}</div></div>
  <div class="laboptions"><label><input type="checkbox" bind:checked={showActions}/>可选操作区</label><label><input type="checkbox" bind:checked={longTitle}/>长标题 / 多标签</label><span>本地演示 · 未接真实 DQE / 权限 / 后端 · 新协议均为草案</span></div>
  <details class="labsettings" bind:open={settingsOpen}><summary>演示设置：时间形态、候选异常、身份信息、可选动作</summary>
    <div class="settingrow"><b>时间</b><label>普通页头形态<select aria-label="普通时间形态" value={periodKind} onchange={e=>{periodKind=e.currentTarget.value;if(periodKind!=='period')mode(periodKind);}}><option value="period">年/季/月/近一年</option><option value="singleMonth">独立单月</option><option value="singleDay">独立单日</option><option value="day">日范围</option><option value="month">月范围</option></select></label><label>数据期策略<select aria-label="数据期策略" bind:value={latestPolicy}><option value="latest">限制最新期</option><option value="complete">仅完整期</option><option value="allow">允许未完成期（草案）</option><option value="missing">所选期间缺数</option></select></label><label>查询窗口（草案）<select aria-label="查询窗口" value={windowMode} onchange={e=>{windowMode=e.currentTarget.value;query('显式查询窗口变化');}}><option value="current">所选当期</option><option value="ytd">年初累计</option></select></label><button onclick={()=>{notice='超出最新期的演示选择已被拒绝；已应用状态和查询数保持';log('日期约束：拒绝未来/超限期');}}>模拟超限输入</button></div>
    <div class="settingrow"><b>候选</b><select aria-label="候选目标" bind:value={candidateTarget}><option value="region">区域</option><option value="model">模型</option><option value="collab">协同小组</option></select>{#each stateChoices as c}<button onclick={()=>candidateState(c[0])}>{c[1]}</button>{/each}<label><input type="checkbox" checked={allowSmb} onchange={e=>constrainSmb(e.currentTarget.checked)}/>允许 SMB 客户</label><label><input type="checkbox" bind:checked={pageReadOnly}/>整页只读</label></div>
    <div class="settingrow"><b>模型响应</b><select aria-label="下一次模型响应" bind:value={modelResponse}><option value="ready">成功</option><option value="empty">空结果</option><option value="failed">失败</option><option value="denied">无权限</option></select><button onclick={()=>{models('failed',1000);models('ready',150);}}>旧失败晚返回</button><button onclick={()=>{models('ready',1000);models('empty',150);}}>旧成功晚返回</button><button onclick={invalidateContext}>模拟身份失效</button><button onclick={initialize}>重新初始化（参数→导航→候选）</button></div>
    <div class="settingrow"><b>身份</b><select aria-label="身份信息状态" bind:value={identityState}><option value="normal">完整</option><option value="missing">字段缺失</option><option value="loading">加载中</option><option value="failed">加载失败</option></select><label><input type="checkbox" bind:checked={dynamicTitle}/>标题引用已应用期间</label><label>项目名称<input aria-label="演示项目名称" value={entity.name} oninput={e=>entity={...entity,name:e.currentTarget.value}}/></label></div>
    <div class="settingrow"><b>操作</b>{#each actionChoices as a}<label><input type="checkbox" checked={chosenActions.includes(a[0])} onchange={e=>chosenActions=e.currentTarget.checked?[...chosenActions,a[0]]:chosenActions.filter(x=>x!==a[0])}/>{a[1]}</label>{/each}<select aria-label="操作响应" bind:value={actionOutcome}><option value="success">成功</option><option value="failed">失败</option><option value="unavailable">能力不可用</option></select><label><input type="checkbox" checked={deferredApply} onchange={e=>{deferredApply=e.currentTarget.checked;pendingPatch={};log('切换'+(deferredApply?'草稿应用':'即时应用')+'模式；不触发查询');}}/>草稿应用模式</label></div>
  </details>
</div>
<main bind:this={canvas} class:dark class="canvas" style:max-width={width==='auto'?'none':width+'px'}>
  <div class="breadcrumb">经营分析 <span>/</span> 项目地图 <span>/</span> {scene==='flow'?{overview:'项目概览',list:'机会点清单',detail:'项目详情'}[flowPage]:scenes.find(x=>x[0]===scene)?.[1]}<small>演示数据最新月 2026-09 · 日锚点 2026-10-19</small></div>
  <section class="ioc-header layout-{variant}" aria-label="IOC 公共页头">
    {#if scene!=='contract'}<div class="identity"><div class="titleline">{#if stack.length}<button class="back" aria-label="返回来源" onclick={back}>←</button>{/if}<h1>{title}{#if longTitle&&!detail}——全球商业客户跨区域协同建设与重点项目经营分析专题看板{/if}</h1></div>
      {#if detail&&contextReady&&identityState!=='missing'}<div class="tags"><span class="code">项目编码：{entity.id}</span>{#each [...entity.tags,...(longTitle?['海外','跨 BG 协同','年度跟踪']:[])] as t}<span class="tag tag-{tagTone[t]??'neutral'}">{t}</span>{/each}</div>{/if}
      <p class="description">{identityState==='loading'?'正在加载身份信息，当前合法筛选保持':identityState==='failed'?'身份信息加载失败，可在演示设置重试，已知身份保持':identityState==='missing'?'业务信息暂缺':detail?'项目身份来自显式导航实体键 · 详情仅接受单月':scene==='time'?'独立单日、月、范围及模式联动；周协议为草案':'按区域、期间查看项目与机会点进展'}{#if identityState!=='missing'}<span class="refresh">数据刷新：2026-10-18 08:30</span>{/if}</p>
    </div>{/if}
    <div class="filterarea"><div bind:this={filterRow} class="filters" class:collapsed={dense&&!expanded&&overflow} style:max-height={dense&&!expanded&&overflow?firstRowHeight+'px':undefined}>
      <div class="field"><span>区域</span><TreeSelect label="区域" nodes={regionNodes} value={shown.region} disabled={pageReadOnly||candidate!=='ready'} reason={pageReadOnly?'整页只读':stateText[candidate]} onchange={changeRegion}/></div>
      {#if scene==='contract'}<div class="field"><span>月份</span><MultiSelect label="离散月份" options={monthOptions} value={shown.months} disabled={pageReadOnly} onchange={v=>commit({months:v},'离散月份集合应用，不填补间隔')}/></div>
      {:else if detail}<div class="field"><DatePicker label="详情单月" precision="month" required disabled={pageReadOnly} value={{from:shown.month,to:shown.month}} onchange={v=>{if(v)singleMonth(v.from);}}/></div>
      {:else if scene!=='time'}<div class="field period-field">{#if periodKind==='period'}<PeriodPrototype value={shown.period} anchor={shown.periodAnchor} readOnly={pageReadOnly} onchange={applyPeriod}/>{:else}<TimeControl mode={periodKind} from={periodKind==='singleMonth'?shown.month+'-01':shown.from} to={shown.to} disabled={pageReadOnly} onchange={(from,to)=>dates(from,to,periodKind)}/>{/if}</div>{/if}
      {#if scene!=='contract'}<div class="field"><span>币种</span><div class="segmented">{#each ['RMB','USD'] as c}<button class:chosen={shown.currency===c} disabled={pageReadOnly} onclick={()=>currency(c)}>{c}</button>{/each}</div></div>{/if}
      {#if dense||scene==='money'}<div class="field"><span>预签金额</span><button class="amount" disabled={pageReadOnly} onclick={money}>{amounts} ⌄</button></div>{/if}
      {#if dense}{#each dims as d}<div class="field"><span>{d.label}</span>
        {#if d.id==='F08'}<TreeSelect label="行业" nodes={industryNodes} value={shown.dims['行业']??[]} disabled={pageReadOnly} onchange={v=>dimension('行业',v)}/>
        {:else}<MultiSelect label={d.label} options={d.id==='F11'?businessOptions:d.id==='F24'?collabOptions:d.id==='F07'?d.options.filter(v=>allowSmb||v!=='SMB'):['F18','F19'].includes(d.id)?[{value:'1',label:'是（1）'},{value:'0',label:'否（0）'}]:d.options} value={shown.dims[d.label]??[]} allMeansUnlimited={['F18','F19'].includes(d.id)} disabled={pageReadOnly||(d.id==='F11'&&!businessOptions.length)||(d.id==='F24'&&(collabState!=='ready'||!collabOptions.length))} reason={pageReadOnly?'上级锁定，只读':d.id==='F11'?'请先选择产业':d.id==='F24'?(!collabOptions.length?'当前区域与业务类型没有可用候选':stateText[collabState]):''} onchange={v=>dimension(d.label,v)}/>{#if d.id==='F11'&&!businessOptions.length}<small class="dependent">需先选产业</small>{/if}{/if}
      </div>{/each}{#each flags as f}<label class="flag" title={f[0]==='F03'?'只影响显式绑定的客户指标':''}><input type="checkbox" disabled={pageReadOnly} checked={!!shown.flags[f[0]]} onchange={e=>commit({flags:{...shown.flags,[f[0]]:e.currentTarget.checked}},f[1])}/>{f[1]}</label>{/each}{/if}
      {#if scene==='time'}<div class="field"><Select label="时间形态" value={shown.mode} disabled={pageReadOnly} options={[{value:'singleDay',label:'独立单日'},{value:'singleMonth',label:'独立单月'},{value:'day',label:'日范围'},{value:'month',label:'月范围'},{value:'week',label:'周（ISO 草案）'},{value:'year',label:'年'},{value:'quarter',label:'季'},{value:'rolling',label:'近一年'},{value:'legacy',label:'旧系统周（不可用）'}]} onchange={mode}/></div><div class="field"><TimeControl mode={shown.mode} from={shown.from} to={shown.to} disabled={pageReadOnly} onchange={(from,to)=>dates(from,to)}/></div>{/if}
      {#if scene==='time'||scene==='edge'}<div class="field"><span>模型</span><MultiSelect label="模型" options={modelOptions} value={shown.dims['模型']??[]} disabled={pageReadOnly||modelState!=='ready'} reason={stateText[modelState]} onchange={v=>dimension('模型',v)}/><small>{stateText[modelState]}</small></div>{/if}
    </div>{#if dense&&overflow}<button class="expand" aria-expanded={expanded} onclick={()=>{expanded=!expanded;log((expanded?'展开':'收起')+'筛选；不提交、不查询');}}>{expanded?'收起筛选 ⌃':'展开全部筛选 ⌄'}</button>{/if}</div>
    {#if showActions}<div class="actions">
      {#if chosenActions.includes('theme')}<button onclick={()=>dark=!dark}>{dark?'浅色':'深色'}</button>{/if}{#if chosenActions.includes('fullscreen')}<button onclick={full}>全屏 / 退出</button>{/if}
      {#if chosenActions.includes('xlsx')}<button disabled={!!actionState||paused} onclick={()=>action('XLSX · opportunity-table')}>{actionState||'导出表格（模拟）'}</button>{/if}
      {#if chosenActions.includes('apply')}<button disabled={!Object.keys(pendingPatch).length||pageReadOnly} onclick={applyDraft}>应用筛选</button>{/if}
      {#if chosenActions.includes('search')}<button disabled title="未配置服务端目标源及搜索范围，保持不可用">全页搜索 · 不可用</button>{/if}
      {#if chosenActions.some(a=>['pdf','refresh','reset'].includes(a))}<details><summary>更多</summary><div class="menu">{#if chosenActions.includes('pdf')}<button disabled={!!actionState||paused} onclick={()=>action('PDF 整页下载')}>PDF 下载（模拟）</button>{/if}{#if chosenActions.includes('refresh')}<button onclick={()=>query('刷新已应用条件，忽略未应用草稿')}>刷新数据</button>{/if}{#if chosenActions.includes('reset')}<button disabled={pageReadOnly} onclick={()=>commit(defaults(),'按明确默认基线重置')}>重置筛选</button>{/if}</div></details>{/if}
    </div>{/if}
    {#if dense}<div class="summary">已应用：{regionLabels||'授权范围内不限'} · {periodLabel} · {applied.currency} · {amounts}{#each Object.entries(effectiveDimensions) as [key,v]}<span class="summarytag">{key}：{displayDimension(key,v)}</span>{/each}{#each flags.filter(f=>applied.flags[f[0]]) as f}<span class="summarytag">{f[1]}</span>{/each}</div>{/if}
  </section>
  {#if scene==='time'}<section class="time-options"><span>含锚点日的近 N 天</span>{#each [1,7,30,90] as n}<button disabled={pageReadOnly||!['day','singleDay'].includes(applied.mode)} onclick={()=>recent(n)}>近{n}天</button>{/each}{#if ['month','singleMonth'].includes(applied.mode)}{#each [1,3,12] as n}<button onclick={()=>recentMonths(n)}>近{n}完整月</button>{/each}{/if}<span>最新月 {latest}；最新日 {anchor}；完整日截止 10-18</span></section>{/if}
  {#if pageReadOnly}<div class="status">本页只读：来自上级锁定视图；保留已应用值，控件不提交。</div>{/if}
  {#each [['区域',candidate],['模型',modelState],['协同小组',collabState]].filter(([,s])=>s!=='ready') as [label,s]}<div class="status">{label}：{stateText[s]}。{s==='readonly'?'来自上级，只读；与无权限不同。':'保留合法已选值；不可信候选不会回退全部，依赖查询暂停。'}{#if s==='failed'}<button onclick={()=>{candidateTarget=label==='区域'?'region':label==='模型'?'model':'collab';if(label==='模型')models();else candidateState('ready');}}>重试{label}候选</button>{/if}</div>{/each}
  {#if Object.keys(pendingPatch).length}<div class="draftbanner">待应用草稿：{JSON.stringify(pendingPatch)}<button onclick={applyDraft}>应用全部草稿</button><button onclick={()=>{pendingPatch={};log('取消全部草稿；已应用状态保持');}}>取消全部草稿</button></div>{/if}
  {#if actionError}<div class="notice" role="alert">{actionError}<button onclick={retryAction}>重试操作</button></div>{/if}
  {#if restored}<div class="restored">✓ {restored}</div>{/if}{#if notice}<div class="notice" role="status">{notice}<button aria-label="关闭提示" onclick={()=>notice=''}>×</button></div>{/if}
  <div class="scope"><span>查询期间：<b>{period}</b></span><span>币种 / 金额：{applied.currency} · {amounts}</span><span class="querycount">模拟查询提交 {queries} 次{paused?' · 暂停':''}</span></div>
  <div class="period-info">查询窗口：{windowMode==='ytd'?'年初累计':'所选当期'} · 数据最新期：{scene==='time'?anchor:latest} · 完成状态：{latestPolicy==='allow'?'允许未完成期（演示声明）':latestPolicy==='missing'?'本期缺数':'按所选数据期策略'}</div>
  {#if scene==='contract'}<div class="contract-note">按月份集合匹配：<b>{applied.months.join('、')||'未选择'}</b>。选 1 月和 3 月不包含 2 月。</div>{/if}
  {#if scene==='flow'}<div class="flowbar"><span>业务链路：<b>{{overview:'① 概览',list:'② 列表',detail:'③ 详情'}[flowPage]}</b> · 来源实例 {stack.map(s=>s.instance).join(' → ')||'无'}</span>{#if flowPage==='overview'}<Button variant="primary" onclick={()=>go('list')}>进入机会点清单 →</Button>{:else if flowPage==='list'}<Button variant="primary" onclick={()=>go('detail',0)}>打开首条项目详情 →</Button><button onclick={()=>go('detail',undefined,true)}>模拟缺少实体键</button>{/if}{#if stack.length}<button onclick={()=>{revision++;notice='已模拟文档修订变化，返回时验证快照兼容性。';}}>模拟修订变化</button>{/if}</div>{/if}
  {#if !contextReady}<section class="emptybody">可信上下文尚未就绪，旧数据与详情已失效。<button onclick={initialize}>初始化新上下文</button></section>
  {:else if latestPolicy==='missing'}<section class="emptybody">所选期间没有数据，保留页头和已应用条件；不将缺数显示为 0。</section>
  {:else}
  {#if !dense&&!detail}<div class="metrics">{#each [['机会点数','128','个'],['已立项数','46','个'],['预签金额',applied.currency==='RMB'?'82,600,000':'11,400,000',applied.currency==='RMB'?'元':'美元'],['重点项目','18','个']] as m}<div><span>{m[0]}</span><strong>{m[1]}<small>{m[2]}</small></strong><em>本地样例 · {applied.currency==='USD'?'独立 USD 字段，未换算':'静态数值'}</em></div>{/each}</div>{/if}
  <section class="bodypanel"><div class="bodytop"><div class="tabs">{#each (detail?['项目概况','跟进记录']:['机会点','已立项']) as t}<button class:active={tab===t} onclick={()=>{tab=t;log('正文 Tab：'+t);}}>{t}</button>{/each}</div><span>正文示意 · 表内搜索与表头条件留在正文</span></div>
    {#if detail}<div class="detailbody"><div><small>项目键</small><b>{entity.id}</b></div><div><small>客户名称</small><b>全球商业客户 A</b></div><div><small>所属区域</small><b>{regionLabels||'演示授权范围'}</b></div><div><small>数据性质</small><b>本地模拟，业务数据未接通</b></div></div>
    {:else}<div class="tabletools"><span>机会点清单 <b>128</b><small>（演示总数）</small></span><div><input aria-label="表内搜索" placeholder="表内搜索项目名称" value={search} oninput={e=>{search=e.currentTarget.value;page=1;}}/><select aria-label="阶段表头条件" value={columnStage} onchange={e=>{columnStage=e.currentTarget.value;page=1;query('阶段表头条件变化');}}><option value="">阶段不限</option><option value="验证">验证</option><option value="方案">方案</option></select><button onclick={()=>{sort=sort==='金额降序'?'金额升序':'金额降序';page=1;query('正文排序');}}>{sort} ↕</button><button disabled={!!actionState||paused} onclick={()=>action('XLSX · opportunity-table')}>导出 XLSX（模拟）</button></div></div>
    <div class="tablewrap"><table><thead><tr><th>项目 / 机会点名称</th><th>区域</th><th>阶段</th><th>预签金额（{applied.currency==='RMB'?'元':'美元'}）</th><th>项目级别</th></tr></thead><tbody>{#each rows as i (i)}<tr><td><button class="link" onclick={()=>scene==='flow'?go('detail',i):(notice='完整行导航在“跨页流程”中演示；实体键为 '+entityAt(i).id)}>{entityAt(i).name}</button><small>{entityAt(i).id}</small></td><td>{regionLabels||['欧洲地区部','亚太地区部'][i%2]}</td><td><span class="tag tag-blue">{i%2?'方案':'验证'}</span></td><td class="number">{(applied.currency==='RMB'?8600000-i*120000:1200000-i*17000).toLocaleString()}</td><td>{i%2?'一般项目':'重点项目'}</td></tr>{/each}</tbody></table></div><div class="pagination"><span>第 {page} 页 · 每页 6 条 · 演示总数 128</span>{#each [1,2,3] as p}<button class:active={page===p} onclick={()=>{page=p;query('表格翻页 '+p);}}>{p}</button>{/each}</div>{/if}
  </section>{/if}
  <footer class="footnote">PROTOTYPE · 验证布局与交互；数据、候选、身份与任务均为本地模拟。周、搜索及跨窗口/刷新恢复的真实集成边界见88项清单。</footer>
</main>
<dialog bind:this={moneyPanel} aria-labelledby="money-title" class="moneydialog" onclose={()=>amountOpen=false} oncancel={()=>{amountOpen=false;amountError='';}}><div class="dialogtitle"><h2 id="money-title">预签金额</h2><button aria-label="关闭金额面板" onclick={closeMoney}>×</button></div><p>单位：{shown.currency==='RMB'?'人民币元':'美元'} · 闭区间，可填单边</p><div class="presets">{#each (shown.currency==='RMB'?[['全部','',''],['≤ 200 万','','2000000'],['200 万—1000 万','2000000','10000000']]:[['全部','',''],['≤ 1M','','1000000'],['1M—5M','1000000','5000000']]) as preset}<button onclick={()=>{minDraft=preset[1];maxDraft=preset[2];amountError='';}}>{preset[0]}</button>{/each}</div><label>最小金额<input aria-label="最小金额" aria-describedby="amount-error" inputmode="decimal" bind:value={minDraft} placeholder="不限"/></label><label>最大金额<input aria-label="最大金额" aria-describedby="amount-error" inputmode="decimal" bind:value={maxDraft} placeholder="不限"/></label><div id="amount-error" class="error" role="alert">{amountError}</div><p class="draftnote">面板草稿：{minDraft||'不限'} ～ {maxDraft||'不限'}；已应用：{amounts}</p><div class="dialogfoot"><Button onclick={()=>{closeMoney();log('取消金额面板草稿；已应用与查询数保持');}}>取消</Button><Button variant="primary" onclick={applyMoney}>确定</Button></div></dialog>
{#if inspect}<aside class="inspector"><div><b>状态观察</b><button onclick={()=>inspect=false}>关闭</button></div><p>模拟提交：{queries} · 滚动：{scrollNote||'0px'}</p><details open><summary>已应用值</summary><pre>{JSON.stringify(applied,null,2)}</pre></details><details><summary>模拟有效请求（非真实 DQE）</summary><pre>{JSON.stringify(effectiveRequest,null,2)}</pre></details><details open><summary>有效维度条件（双选是/否不加条件）</summary><pre>{JSON.stringify(effectiveDimensions,null,2)}</pre></details><details><summary>草稿与候选</summary><pre>{JSON.stringify({pendingPatch,amountOpen,minDraft,maxDraft,amountError,candidate,modelState,collabState,generation,contextReady,queryPending},null,2)}</pre></details><details><summary>当前视图与来源快照</summary><pre>{JSON.stringify({page,sort,tab,search,columnStage,entity,expanded,revision,stack},null,2)}</pre></details><details><summary>任务捕获的已应用快照</summary><pre>{JSON.stringify(lastExport,null,2)}</pre></details><h3>事件记录</h3>{#each events as e}<p class="event">{e}</p>{/each}</aside>{/if}
{#if coverage}<aside class="coverage"><div><b>88项原型覆盖与边界</b><button onclick={()=>coverage=false}>关闭</button></div><p>每项明确列出场景、操作步骤和集成边界；“交互样例”仅指本地演示，不表示生产实现。没有默认的“已完成”标签。</p>{#each features as f}{@const c=coverageFor(f.id)}<div class="coverageitem"><div class="feature"><code>{f.id}</code><span>{f.label}</span><small>{c.status}</small></div><p>{c.note}</p><button onclick={()=>{chooseScene(c.scene);coverage=false;if(c.scene==='dense')expanded=true;}}>查看场景：{scenes.find(s=>s[0]===c.scene)?.[1]}</button><small>{c.steps}</small></div>{/each}</aside>{/if}
{#if import.meta.env.DEV}<nav class="switcher" aria-label="原型布局比较"><button aria-label="上一布局" onclick={()=>cycle(-1)}>←</button><div><small>布局比较 · 内部视觉 A</small><b>{variant} · {layouts.find(x=>x[0]===variant)?.[1]}</b></div><button aria-label="下一布局" onclick={()=>cycle(1)}>→</button></nav>{/if}
